/* voica-all launcher — an Actually Portable Executable (Cosmopolitan).
 *
 * This one file is the executable on every OS. Inside it are the three
 * per-OS Voica hosts plus recorder.wasm (embedded as byte arrays in
 * payloads.h, generated by gen_payloads.py from the v0.0.1 release
 * artifacts). At run time it detects the OS, extracts the matching
 * host + the wasm to a cache dir, and runs the host on the wasm.
 * Nothing needs to be installed beforehand.
 */
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/utsname.h>
#include <sys/wait.h>
#include <unistd.h>

#include "payloads.h"

extern char **environ;

static int write_file(const char *path, const unsigned char *data,
                      unsigned int len, int executable) {
  FILE *f = fopen(path, "wb");
  if (!f) return -1;
  if (len && fwrite(data, 1, len, f) != len) { fclose(f); return -1; }
  fclose(f);
  if (executable) chmod(path, 0755);
  return 0;
}

static int run_host(const char *host_path, const char *wasm_path,
                    int argc, char **argv);

int main(int argc, char **argv) {
  /* --- detect OS --- */
  int is_win = 0, is_mac = 0;
  const char *osenv = getenv("OS");
  struct utsname un;
  uname(&un);
  if ((osenv && strstr(osenv, "Windows")) || strstr(un.sysname, "Windows"))
    is_win = 1;
  else if (!strcmp(un.sysname, "Darwin") || strstr(un.sysname, "XNU"))
    is_mac = 1;

  const unsigned char *host_data;
  unsigned int host_len;
  const char *host_name;
  if (is_win) {
    host_data = payload_win32; host_len = payload_win32_len;
    host_name = "voica-host.exe";
  } else if (is_mac) {
    host_data = payload_darwin; host_len = payload_darwin_len;
    host_name = "voica-host";
  } else {
    host_data = payload_linux; host_len = payload_linux_len;
    host_name = "voica-host";
  }

  /* --- pick a cache dir --- */
  const char *base = getenv("HOME");
  if (!base || !*base) base = getenv("USERPROFILE");
  if (!base || !*base) base = getenv("TEMP");
  if (!base || !*base) base = ".";
  char dir[1024], host_path[1100], wasm_path[1100];
  snprintf(dir, sizeof dir, "%s/.voica-all", base);
  mkdir(dir, 0755);
  snprintf(host_path, sizeof host_path, "%s/%s", dir, host_name);
  snprintf(wasm_path, sizeof wasm_path, "%s/recorder.wasm", dir);

  /* --- extract (overwrite: payloads are versioned by the binary) --- */
  if (write_file(host_path, host_data, host_len, 1) != 0) {
    fprintf(stderr, "voica-all: cannot extract host to %s\n", host_path);
    return 1;
  }
  if (write_file(wasm_path, payload_recorder_wasm,
                 payload_recorder_wasm_len, 0) != 0) {
    fprintf(stderr, "voica-all: cannot extract app to %s\n", wasm_path);
    return 1;
  }

  /* --- run the host on the app, from the caller's cwd so the
         recorded voica-out.wav lands where the user ran us --- */
  return run_host(host_path, wasm_path, argc, argv);
}

/* Spawn the extracted host directly with an argv array — no shell
 * command string, so arguments reach the host byte-for-byte (a path
 * with spaces or quotes can no longer be mangled by re-quoting the
 * way the old system() launch mangled it). The host's exit status is
 * decoded and returned as-is: a host exit 1 comes back as 1, not as
 * the raw wait status (256) the old code leaked. If the host cannot
 * be started at all, the OS reason is printed and the exit is 127. */
static int run_host(const char *host_path, const char *wasm_path,
                    int argc, char **argv) {
  char **child_argv = malloc(sizeof(char *) * ((size_t)argc + 3));
  if (!child_argv) return 127;
  child_argv[0] = (char *)host_path;
  child_argv[1] = (char *)wasm_path;
  /* Any arguments we were given are passed through to the host:
       voica-all [seconds] [--out <path>] */
  for (int i = 1; i < argc; i++) child_argv[i + 1] = argv[i];
  child_argv[argc + 1] = NULL;

  /* Error pipe: the write end is close-on-exec, so a successful
   * execve closes it and the parent reads EOF; a failed execve lets
   * the child hand its errno back before it dies. */
  int errpipe[2];
  if (pipe(errpipe) != 0) {
    fprintf(stderr, "voica-all: cannot start host %s: %s\n",
            host_path, strerror(errno));
    free(child_argv);
    return 127;
  }
  fcntl(errpipe[1], F_SETFD, FD_CLOEXEC);

  pid_t pid = fork();
  if (pid == 0) {
    close(errpipe[0]);
    execve(host_path, child_argv, environ);
    int e = errno;
    ssize_t ignored = write(errpipe[1], &e, sizeof e);
    (void)ignored;
    _exit(127);
  }
  if (pid < 0) {
    fprintf(stderr, "voica-all: cannot start host %s: %s\n",
            host_path, strerror(errno));
    close(errpipe[0]);
    close(errpipe[1]);
    free(child_argv);
    return 127;
  }
  close(errpipe[1]);
  int child_errno = 0;
  ssize_t got = read(errpipe[0], &child_errno, sizeof child_errno);
  close(errpipe[0]);

  int status = 0;
  pid_t waited;
  while ((waited = waitpid(pid, &status, 0)) < 0 && errno == EINTR) {
  }
  free(child_argv);

  if (got == (ssize_t)sizeof child_errno) {
    fprintf(stderr, "voica-all: cannot start host %s: %s\n",
            host_path, strerror(child_errno));
    return 127;
  }
  if (waited < 0) return 1;
  if (WIFEXITED(status)) return WEXITSTATUS(status);
  if (WIFSIGNALED(status)) return 128 + WTERMSIG(status);
  return 1;
}
